/* ================= V45 ================= */
/* ---------- one master record per mobile number: the latest details given win ---------- */
function pplPut(o,src,t){if(!o)return null;const mob=normMob(o.mobile||'');if(!mobOk(mob)||!String(o.name||'').trim())return null;S.people=S.people||{};t=+t||Date.now();
  const r=S.people[mob]||(S.people[mob]={mobile:mob,at:0,first:t,srcs:[],accs:[]}),F=['name','place','des','rel','address'];
  if(t>=r.at){if(o.name&&r.name&&r.name!==String(o.name).trim()&&!o.alt)delete r.alt;F.forEach(k=>{const v=o[k];if(v!=null&&String(v).trim())r[k]=String(v).trim()});if(o.alt)r.alt=Object.assign({},r.alt||{},o.alt);r.at=t;r.src=src||r.src}
  else F.forEach(k=>{if(!r[k]&&o[k])r[k]=String(o[k]).trim()});
  if(src&&!r.srcs.includes(src))r.srcs.push(src);if(o.acc&&!r.accs.includes(o.acc))r.accs.push(o.acc);r.first=Math.min(r.first||t,t);return r}
const pplGet=mob=>(S.people||{})[normMob(mob||'')]||null;
const moiPpl=m=>({mobile:m.c.mobile,name:m.c.name,place:m.c.place,des:m.c.designation,rel:m.c.relationship,address:m.c.address,alt:m.c.alt,acc:(S.events.find(e=>e.id===m.event_id)||{}).acc});
function pplSeed(){S.people=S.people||{};const L=[];
  S.moi.forEach(m=>L.push([m.c.updatedAt||m.created_at||0,'moi',moiPpl(m)]));
  (S.guests||[]).forEach(r=>L.push([r.at||0,'guest',{mobile:r.mobile,name:r.name,place:r.place,des:r.des,rel:r.rel,address:r.address,acc:r.acc}]));
  L.sort((a,b)=>a[0]-b[0]).forEach(([t,src,o])=>pplPut(o,src,t||1));S.pplV45=1}
/* fill a staff Moi form from the master record */
function pplFill(f,px,p){[['name',p.name],['place',p.place],['des',p.des]].forEach(([id,v])=>{const el=f.querySelector('#'+px+'_'+id);if(el&&v){el.value=v;el.classList.remove('invalid')}});
  const a=f.querySelector('#'+px+'_addr');if(a&&p.address&&!a.value)a.value=p.address;const al=f.querySelector('#m_alt');if(al){const lg=al.dataset.lg;al.value=translit((p.alt&&p.alt[lg])||p.name,lg);al.dataset.touched=p.alt&&p.alt[lg]?'1':''}}
const pplSrcTxt=p=>p.srcs.includes('moi')&&p.srcs.includes('guest')?'Moi Point records and guest lists':p.srcs.includes('guest')?'a guest list on Moi Point':'Moi Point records';

/* ---------- function status that moves by itself: upcoming → live → completed → all done ---------- */
const DONE_DAYS=15;
Object.assign(EVST,{upcoming:['Upcoming','info'],live:['Live now','good'],done:['All done','mute']});
const evStartAt=ev=>new Date(ev.date+'T'+(ev.start&&ev.start.length===5?ev.start:'00:00')+':00').getTime();
function evPh(ev){if(!ev)return 'draft';if(['void','draft','archived'].includes(ev.status)||!ev.date)return ev.status;const n=Date.now(),e=evEndAt(ev);
  if(n<evStartAt(ev))return 'upcoming';if(n<=e)return 'live';if(n<e+DONE_DAYS*864e5)return 'completed';return 'done'}
function evAuto(){let ch=0;S.events.forEach(ev=>{if(!ev.date||!['active','completed'].includes(ev.status))return;const w=Date.now()>evEndAt(ev)?'completed':'active';if(ev.status!==w){ev.status=w;ch=1}});return ch}
function phTxt(ev){const p=evPh(ev);
  if(p==='upcoming'){const d=Math.round((new Date(ev.date+'T00:00:00')-new Date(today()+'T00:00:00'))/864e5);return d<=0?`Today · starts ${tfmt(ev.start)}`:d===1?`Tomorrow · ${tfmt(ev.start)}`:`In ${d} days`}
  if(p==='live')return `Live now · till ${tfmt(ev.end)}`;
  if(p==='completed'){const l=Math.max(1,Math.ceil((evEndAt(ev)+DONE_DAYS*864e5-Date.now())/864e5));return l===1?'Completed · all done tomorrow':`Completed · all done in ${l} days`}
  return p==='done'?'All done':p==='void'?'Void · final':p==='draft'?'Draft · not started':p==='archived'?'Archived':''}
const phChip=ev=>{const p=evPh(ev);return `<span class="ph-chip ph-${p}">${p==='live'?'<i class="ph-live"></i>':ic(p==='upcoming'?'clock':p==='void'?'x':p==='done'||p==='completed'?'check':'edit',13)}${phTxt(ev)}</span>`};

/* ---------- Our Functions: every function, past, live and upcoming ---------- */
const fnq={tab:'all',q:''};const PHORD=['live','upcoming','completed','done','draft','archived','void'];
const PHLBL={live:'Live now',upcoming:'Upcoming',completed:'Completed',done:'All done',draft:'Draft',archived:'Archived',void:'Void'};
function fnCard(e){const t=calc(e.id),p=evPh(e),mg=manages(e.id);
  return `<article class="fn-card fc-${p}"><button class="fn-cv" data-go="#ev-${e.id}-overview" aria-label="Open ${esc(e.name)}">${evCover(e)}${phChip(e)}</button>
  <div class="fn-b"><div class="fn-t"><b>${esc(e.name)}</b><small>${esc(e.type)} · ${esc(e.no||'')}</small></div>
   <p class="fn-m">${ic('cal',15)}${dfmt(e.date)} · ${tfmt(e.start)} – ${tfmt(e.end)}</p><p class="fn-m">${ic('pin',15)}${esc(e.venue||'—')}</p>
   <div class="fn-s"><span><b>${fmt(t.total)}</b>Moi</span><span><b>${t.okN||0}</b>entries</span>${mg?`<span><b>${fmt(t.net)}</b>balance</span>`:''}</div>
   <div class="btn-row">${p==='live'||((p==='upcoming'||p==='completed')&&takesMoi(e))?`<button class="btn btn-primary btn-sm" data-go="#ev-${e.id}-receive">${ic('plus',16)}Receive Moi</button>`:''}${me.role==='admin'&&e.status!=='void'?`<button class="btn btn-ghost btn-sm" data-act="evEdit" data-id="${e.id}">${ic('edit',15)}Edit</button>`:''}<button class="btn btn-ghost btn-sm" data-go="#ev-${e.id}-overview">Open ${ic('arrow',15)}</button></div></div></article>`}
function vFunctions(){const all=myEvents(),q=fnq.q.toLowerCase(),cnt=k=>all.filter(e=>k==='all'||evPh(e)===k).length;
  const tabs=[['all','All'],['live','Live now'],['upcoming','Upcoming'],['completed','Completed'],['done','All done'],['draft','Draft'],['void','Void']].filter(([k])=>k==='all'||k==='live'||k==='upcoming'||cnt(k));
  const L=all.filter(e=>(fnq.tab==='all'||evPh(e)===fnq.tab)&&(!q||(e.name+e.type+e.venue+(e.no||'')+e.organizer).toLowerCase().includes(q)));
  const sortP=(a,b)=>{const p=evPh(a);return p==='upcoming'?a.date.localeCompare(b.date):b.date.localeCompare(a.date)};
  const groups=PHORD.map(p=>[p,L.filter(e=>evPh(e)===p).sort(sortP)]).filter(g=>g[1].length);
  const nx=all.filter(e=>evPh(e)==='upcoming').sort((a,b)=>a.date.localeCompare(b.date))[0],lv=all.filter(e=>evPh(e)==='live');
  return `<div class="page-head"><div><h1>Our Events / Functions</h1><p class="sub">Every function in one place: live now, coming up and finished. Tap one to go inside.</p></div>${me.role==='admin'?`<button class="btn btn-primary" data-act="evNew">${ic('plus')}Create Event</button>`:''}</div>
  <div class="fn-hero">${lv.length?`<div class="fh live"><i class="ph-live"></i><div><b>${lv.length===1?esc(lv[0].name)+' is live now':lv.length+' functions are live now'}</b><small>${lv.length===1?'Till '+tfmt(lv[0].end):'Open one to receive Moi'}</small></div>${lv.length===1?`<button class="btn btn-white btn-sm" data-go="#ev-${lv[0].id}-receive">Receive Moi</button>`:''}</div>`:''}
   ${nx?`<div class="fh next">${ic('clock',22)}<div><b>Next: ${esc(nx.name)}</b><small>${phTxt(nx)} · ${dfmt(nx.date)}, ${tfmt(nx.start)}</small></div><button class="btn btn-ghost btn-sm" data-go="#ev-${nx.id}-overview">Open</button></div>`:''}
   <div class="fh stat"><span><b>${cnt('upcoming')}</b>upcoming</span><span><b>${cnt('live')}</b>live</span><span><b>${cnt('completed')+cnt('done')}</b>finished</span></div></div>
  <div class="fn-bar"><div class="seg fn-seg" role="tablist">${tabs.map(([k,l])=>`<button role="tab" class="${fnq.tab===k?'on':''}" data-act="fnTab" data-k="${k}">${l} <span class="seg-n">${cnt(k)}</span></button>`).join('')}</div>
   <div class="filters ev-search"><div class="search">${ic('search',18)}<input class="inp" id="fnQ" placeholder="Search functions" value="${esc(fnq.q)}" aria-label="Search functions"></div></div></div>
  <div id="fnRows">${groups.length?groups.map(([p,es])=>`<section class="fn-g"><h2 class="fn-gh fg-${p}">${PHLBL[p]} <span>${es.length}</span></h2><div class="fn-grid">${es.map(fnCard).join('')}</div></section>`).join(''):`<div class="card">${emptyBox('No functions here','Pick another tab, or create a new function.')}</div>`}</div>`}

/* ---------- Moi List: pin close family to the top ---------- */
const pinsOf=ev=>(ev&&ev.pins||[]).filter(id=>S.moi.some(m=>m.id===id&&m.event_id===ev.id&&(m.status==='received'||m.status==='verified')));
function pinBox(ev,mg){const P=pinsOf(ev).map(id=>S.moi.find(m=>m.id===id));if(!P.length)return '';
  return `<section class="pin-box"><div class="pin-h">${ic('pin',18)}<b>Pinned at the top</b><small>${P.length} · close family and key relatives. ${mg?'Use the arrows to set the order.':''}</small></div>
  <ol class="pin-l">${P.map((m,i)=>`<li><span class="pin-n">${i+1}</span><button class="pin-who" data-act="moiView" data-id="${m.id}"><b>${esc(m.c.name)}</b><small>${esc(m.c.relationship||'—')} · ${esc(m.c.place||'—')} · ${m.code}</small></button><span class="pin-amt">${esc(amtTxt(m))}</span>
   ${mg?`<span class="pin-a"><button class="icon-btn icon-sm" data-act="pinMv" data-id="${m.id}" data-d="-1" ${i?'':'disabled'} aria-label="Move up">${ic('down',16)}</button><button class="icon-btn icon-sm dn" data-act="pinMv" data-id="${m.id}" data-d="1" ${i<P.length-1?'':'disabled'} aria-label="Move down">${ic('down',16)}</button><button class="btn btn-ghost btn-sm" data-act="moiPin" data-id="${m.id}">Unpin</button></span>`:''}</li>`).join('')}</ol></section>`}
const pinBtn=(m,mg,lbl)=>{if(!mg||!(m.status==='received'||m.status==='verified'))return '';const ev=S.events.find(e=>e.id===m.event_id),on=pinsOf(ev).includes(m.id);return lbl?`<button class="btn btn-${on?'soft':'ghost'} btn-sm" data-act="moiPin" data-id="${m.id}">${STAR}${on?'Remove special guest mark':'Mark as close family (pin to top)'}</button>`:`<button class="icon-btn icon-sm pin-t ${on?'on':''}" data-act="moiPin" data-id="${m.id}" aria-label="${on?'Remove special guest mark':'Mark as close family (pin to top)'}" title="${on?'Remove special guest mark':'Mark as close family (pin to top)'}">${STAR}</button>`};

/* ---------- credits: expiry, no refunds, and stock alerts for Master Admin ---------- */
const crValidTill=()=>addDays(today(),+P().pricing.validDays||365);
const NOREF='Credits are not refundable. Once bought, unused or expired credits are not refunded and no money is returned.';
function creditTerms(){const w=S.wallet,nx=typeof nextExpiry==='function'?nextExpiry(w):null,till=w.renewTill||(nx&&nx.date);
  return `<section class="cr-terms"><div class="ct-i">${ic('cal',20)}<div><b>${till?'Your credits are valid till '+dfmt(till):'Valid for '+cr(P().pricing.validDays)+' days from purchase'}</b><small>Any new purchase, or any message sent, starts the ${cr(P().pricing.validDays)} days again for the whole balance.</small></div></div>
   <div class="ct-i warn">${ic('alert',20)}<div><b>No refunds</b><small>${NOREF}</small></div></div></section>`}
function stockAlert(want,src){const pl=P();pl.stockAlerts=pl.stockAlerts||[];const A=curAcc()||{},ow=S.users.find(u=>u.id===A.owner)||{};
  const last=pl.stockAlerts[0];if(last&&last.acc===A.id&&last.want===want&&Date.now()-last.at<60000)return;
  pl.stockAlerts.unshift({id:uid('sa'),at:Date.now(),acc:A.id,accName:A.name||'',who:me?me.name:'',mobile:(me&&me.mobile)||ow.mobile||'',email:(me&&me.email)||ow.email||'',want,stock:pl.stock,src:src||'pack',status:'open'});
  if(pl.stockAlerts.length>200)pl.stockAlerts.length=200;
  pl.adminLog=pl.adminLog||[];pl.adminLog.unshift({at:new Date().toISOString(),who:me?me.name:'Customer',role:'Customer',action:'Credit stock alert',detail:`${A.name||A.id} tried to buy ${want} credits · only ${pl.stock} in stock`});save()}
function stockAlertPanel(){const L=(P().stockAlerts||[]).filter(a=>a.status==='open');if(!L.length)return '';
  return `<section class="xpanel sa-panel"><div class="xph2"><h2>${L.length} customer${L.length>1?'s':''} wanted more credits than we have</h2><p>Top up the stock, then call them back.</p></div><div class="xtw"><table><thead><tr><th>When</th><th>Who tried</th><th>Account</th><th class="r">Wanted</th><th class="r">Stock then</th><th class="r">Short by</th><th></th></tr></thead><tbody>
   ${L.map(a=>`<tr><td>${new Date(a.at).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}</td><td><b>${esc(a.who)}</b><small>${a.mobile?'+91 '+esc(String(a.mobile).slice(0,5)+' '+String(a.mobile).slice(5)):''}${a.email?' · '+esc(a.email):''}</small></td><td>${esc(a.accName)}<small>${esc(a.acc||'')}</small></td><td class="r"><b>${a.want.toLocaleString('en-IN')}</b></td><td class="r">${a.stock.toLocaleString('en-IN')}</td><td class="r neg"><b>${Math.max(0,a.want-a.stock).toLocaleString('en-IN')}</b></td><td><button class="btn btn-ghost btn-sm" data-mact="saDone" data-id="${a.id}">Handled</button></td></tr>`).join('')}</tbody></table></div></section>`}
function stockShort(want){stockAlert(want);openModal(`${mh('Not enough credits right now','We have told the Moi Point team')}<div class="md-b stack" style="gap:12px"><div class="note warn">${ic('alert',20)}<div><b>You asked for ${cr(want)} credits</b><p>Only ${cr(P().stock)} credits are available from Moi Point right now. Our team has your request and will add stock soon.</p></div></div><p class="small muted">You can buy up to ${cr(P().stock)} credits now, or wait for our call.</p></div><div class="md-f"><button class="btn btn-ghost" data-act="close">Close</button>${P().stock>=50?`<button class="btn btn-primary" data-act="pack" data-q="${P().stock}">Buy ${cr(P().stock)} now</button>`:''}</div>`)}

/* ---------- reminders: email calendar and a ringing browser alarm ---------- */
const icsD=(d,t)=>d.replace(/-/g,'')+'T'+String(t||'09:00').replace(':','')+'00';
function remEnd(r){const d=new Date(r.date+'T'+(r.time||'18:00')+':00');d.setHours(d.getHours()+2);return d.getFullYear()+pad(d.getMonth()+1)+pad(d.getDate())+'T'+pad(d.getHours())+pad(d.getMinutes())+'00'}
const remDesc=r=>`${r.person?'Whose function: '+r.person+'. ':''}${r.amount?'Moi to give: ₹'+(+r.amount).toLocaleString('en-IN')+'. ':''}${r.desc||''} · Moi Point reminder`.trim();
function gcalUrl(r){const u=new URLSearchParams({action:'TEMPLATE',text:r.title,dates:icsD(r.date,r.time||'18:00')+'/'+remEnd(r),details:remDesc(r),location:r.place||'',ctz:'Asia/Kolkata'});if(me&&me.email)u.set('add',me.email);return 'https://calendar.google.com/calendar/render?'+u.toString()}
function remIcs(r){const esc2=x=>String(x||'').replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n');
  return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Moi Point//Reminders//EN','METHOD:PUBLISH','BEGIN:VEVENT','UID:'+r.id+'@moipoint.in','DTSTAMP:'+icsD(today(),'00:00'),'DTSTART;TZID=Asia/Kolkata:'+icsD(r.date,r.time||'18:00'),'DTEND;TZID=Asia/Kolkata:'+remEnd(r),'SUMMARY:'+esc2(r.title),'DESCRIPTION:'+esc2(remDesc(r)),'LOCATION:'+esc2(r.place),
    ...(me&&me.email?['ORGANIZER;CN=Moi Point:mailto:reminders@moipoint.in','ATTENDEE;CN='+esc2(me.name)+';RSVP=FALSE:mailto:'+me.email]:[]),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+esc2(r.title),'TRIGGER:-P'+(+r.before||0)+'DT'+Math.max(0,24-+String(r.at||'09:00').slice(0,2))+'H','END:VALARM','BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+esc2(r.title),'TRIGGER:-PT1H','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n')}
function remCalRow(r){if(r.status==='done')return '';return `<div class="rem-cal"><a class="btn btn-ghost btn-sm" href="${esc(gcalUrl(r))}" target="_blank" rel="noopener">${ic('cal',15)}Google Calendar</a><button class="btn btn-ghost btn-sm" data-act="remIcs" data-id="${r.id}">${ic('upload',15)}Calendar file (.ics)</button>${r.calSent?`<span class="tag">${ic('mail',12)}Invite sent to ${esc(r.calSent)}</span>`:''}</div>`}
function remCalInvite(r){if(!me||!me.email||r.calSent===me.email)return;r.calSent=me.email;S.notifications.push({id:uid('n'),owner:me.id,channel:'Email',to:me.email,text:`Calendar invite: ${r.title} on ${dfmt(r.date)}${r.time?' at '+tfmt(r.time):''}. Accept it to get calendar alerts on your phone.`,status:online()?'Sent':WAITING,at:Date.now(),attach:'reminder.ics'})}
function alertsBar(){const s=typeof Notification==='undefined'?'none':Notification.permission;
  return `<section class="card pad alerts-bar"><div class="ab-i">${ic('bell',22)}</div><div class="ab-t"><b>${s==='granted'?'Browser alerts are on':'Ring an alarm on this browser'}</b><small>${s==='granted'?'When a reminder is due, this browser rings for 1 minute and shows Close and Mark as done.':s==='denied'?'Alerts are blocked for this site. Allow notifications in the browser’s site settings.':'Allow notifications so the reminder rings for 1 minute even when you are on another tab.'}${me&&me.email?` Calendar invites go to <b>${esc(me.email)}</b>.`:''}</small></div>
   <div class="btn-row">${s==='default'?`<button class="btn btn-primary btn-sm" data-act="remPerm">${ic('bell',16)}Allow alerts</button>`:''}<button class="btn btn-ghost btn-sm" data-act="remTest">${ic('speaker',16)}Test the alarm</button></div></section>`}
let ringCtx=null,ringTimer=null,ringStop=null,ringQ=[];
function ringTone(sec){try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;ringCtx=ringCtx||new C();if(ringCtx.state==='suspended')ringCtx.resume();const c=ringCtx,g=c.createGain();g.gain.value=.16;g.connect(c.destination);
    const end=c.currentTime+sec;for(let t=c.currentTime+.05;t<end;t+=3){for(let i=0;i<8;i++){const o=c.createOscillator(),e=c.createGain();o.type='sine';o.frequency.value=i%2?1318.5:1046.5;e.gain.setValueAtTime(0,t+i*.15);e.gain.linearRampToValueAtTime(1,t+i*.15+.01);e.gain.exponentialRampToValueAtTime(.001,t+i*.15+.14);o.connect(e);e.connect(g);o.start(t+i*.15);o.stop(t+i*.15+.15)}}
    ringStop=()=>{try{g.gain.cancelScheduledValues(c.currentTime);g.gain.setValueAtTime(0,c.currentTime);g.disconnect()}catch(_){}}}catch(e){}}
function ringOff(){if(ringStop)ringStop();ringStop=null;clearTimeout(ringTimer);try{navigator.vibrate&&navigator.vibrate(0)}catch(_){}const o=document.getElementById('ring');if(o)o.remove();
  if(ringQ.length){const nx=ringQ.shift();setTimeout(()=>ringStart(nx),400)}}
function ringStart(r){if(document.getElementById('ring')){ringQ.push(r);return}const test=!r.id;
  const o=document.createElement('div');o.id='ring';o.className='ring';o.setAttribute('role','alertdialog');o.setAttribute('aria-labelledby','ringT');
  o.innerHTML=`<div class="ring-c"><span class="ring-ic">${ic('bell',34)}<i></i><i></i></span><p class="eyebrow">${test?'Test alarm':'Reminder'}</p><h2 id="ringT">${esc(r.title)}</h2><p class="muted">${r.date?dfmt(r.date)+(r.time?' · '+tfmt(r.time):''):'This is how a due reminder rings.'}${r.place?' · '+esc(r.place):''}</p>${r.amount?`<p class="ring-amt">Moi to give: <b>${fmt(r.amount)}</b></p>`:''}
   <p class="small muted" id="ringLeft">Ringing for 1 minute</p><div class="btn-row" style="justify-content:center"><button class="btn btn-ghost" data-act="ringClose">${ic('x',18)}Close</button>${test?'':`<button class="btn btn-good" data-act="ringDone" data-id="${r.id}">${ic('check',18)}Mark as done</button>`}</div></div>`;
  document.body.appendChild(o);ringTone(60);try{navigator.vibrate&&navigator.vibrate(Array(20).fill([600,400]).flat())}catch(_){}
  try{if(typeof Notification!=='undefined'&&Notification.permission==='granted'){const n=new Notification('Moi Point · '+r.title,{body:(r.date?dfmt(r.date)+(r.time?' · '+tfmt(r.time):''):'Test alarm')+(r.amount?' · Moi '+fmt(r.amount):''),tag:'mp-'+(r.id||'test'),requireInteraction:true});n.onclick=()=>{window.focus();n.close()}}}catch(_){}
  let left=60;const tick=()=>{left--;const el=document.getElementById('ringLeft');if(!el)return;if(left<=0){if(ringStop)ringStop();ringStop=null;el.textContent='Alarm stopped. Close it or mark it done.';return}el.textContent=`Ringing · ${left}s`;ringTimer=setTimeout(tick,1000)};ringTimer=setTimeout(tick,1000)}

/* ---------- Moi Book: WhatsApp and email ---------- */
const bookEmail=ev=>{const A=accOfEv(ev),ow=A&&S.users.find(u=>u.id===A.owner);return ev.orgEmail||(ow&&ow.email)||''};
function bookMailHtml(ev){const b=ev.bookSent||{},t=calc(ev.id),em=b.email||bookEmail(ev),A=accOfEv(ev),n=b.n!=null?b.n:S.moi.filter(m=>m.event_id===ev.id&&m.status!=='void').length,file=b.file||`MoiBook-${String(ev.no||ev.id).replace(/\W/g,'')}.pdf`;
  const r=(l,v,c='')=>`<tr class="${c}"><td>${l}</td><td>${v}</td></tr>`;
  return `<div class="mail" data-noi18n><div class="mail-hd"><div><span>From</span><b>Moi Point &lt;books@moipoint.in&gt;</b></div><div><span>To</span><b>${esc(ev.organizer||(A&&A.name)||'')} &lt;${esc(em||'—')}&gt;</b></div><div><span>Subject</span><b>Your Moi Book · ${esc(ev.name)} · ${n} entries · ${fmt(t.total)}</b></div>${b.at?`<div><span>Sent</span><b>${new Date(b.at).toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit'})}</b></div>`:''}</div>
  <div class="mail-bd"><div class="mail-brand">${mpMark()}<b>${MPW()}</b></div><p>Dear ${esc(first(ev.organizer||(A&&A.name)||'family'))},</p><p>Your function <b>${esc(ev.name)}</b> on ${dfmt(ev.date)} at ${esc(ev.venue||'')} has ended. The full Moi Book is attached as a PDF. Keep it safe for returning Moi later.</p>
   <table class="mail-t">${r('Moi received',`<b>${fmt(t.total)}</b>`)}${r('Entries',n)}${t.pendingN?r('Still pending',t.pendingN):''}${t.goldG?r('Gold',(+t.goldG).toFixed(2)+' g'):''}${r('Expenses','− '+fmt(t.expenses))}${r('Payouts','− '+fmt(t.payouts))}${r('Balance',`<b>${fmt(t.net)}</b>`,'tot')}</table>
   <div class="mail-att">${ic('bill',22)}<div><b>${esc(file)}</b><small>PDF · Moi Book with every entry, gold, gifts, returns, expenses and payouts</small></div></div>
   <p class="mail-btn"><span>Open in Moi Point</span></p><p class="small muted">The same PDF was sent to WhatsApp ${ev.orgMobile||(b.to)?'+91 '+esc(String(b.to||ev.orgMobile).slice(0,5)+' '+String(b.to||ev.orgMobile).slice(5)):''}. Reply to this email if anything looks wrong.</p><p class="small muted">With best wishes,<br>Team Moi Point</p></div></div>`}
function bookMailModal(ev){openModal(`${mh('Moi Book email',esc(ev.name))}<div class="md-b">${bookMailHtml(ev)}</div><div class="md-f"><button class="btn btn-ghost" data-act="close">Close</button><button class="btn btn-soft" data-act="bkOpen">${ic('bill',16)}Open Moi Book</button></div>`,true)}

/* ---------- first login: 1-minute video with music and subtitles, then a guided tour ---------- */
const VSC=[{k:'intro'},{k:'create',ph:'ip-wizard',tap:[50,78]},{k:'team',dk:'desk-event',tap:[30,60]},{k:'receive',ph:'ip-receive',tap:[50,40]},{k:'receipt',ph:'an-receipt',tap:[50,62]},{k:'qr',ph:'an-qrpage',tap:[50,70]},{k:'list',dk:'desk-list',tap:[22,34]},{k:'exp',ph:'an-expenses',ph2:'ip-payouts',tap:[60,30]},{k:'book',dk:'desk-book',tap:[70,30]},{k:'nav',dk:'desk-dash',tap:[8,30]},{k:'end'}];
const VSIC={intro:'heart',create:'plus',team:'users',receive:'cash',receipt:'msg',qr:'qr',list:'list',exp:'bill',book:'bill',nav:'grid',end:'check'};
const VSUB={
en:[['Welcome to Moi Point','In one minute, see how to run your function’s Moi from start to finish.'],['Create your function','Tap “Create Event / Function”. Add the name, date, time, venue and the ways you will receive Moi.'],['Add your helpers','Add as many Moi collectors and event admins as you need. Choose what each one can open.'],['Receive Moi at the counter','Type the guest’s mobile. Known guests fill in by themselves. Enter the amount and save.'],['Receipt on WhatsApp','The guest gets a receipt on WhatsApp or SMS straight away.'],['QR page for guests','Guests scan the QR to give Moi by UPI or online. Cash is confirmed at the counter.'],['Moi List','See every Moi. Search, pin close family to the top and mark what you returned.'],['Expenses and payouts','Note every expense and every payout, so the balance is always right.'],['Moi Book','When the function ends, the Moi Book PDF comes to your WhatsApp and email.'],['Find your way','Use the menu: Home, Our Functions, Guest list, Reminders and Credits.'],['You are ready','Create your first function now. Watch this video again any time from Home.']],
ta:[['Moi Point-க்கு வரவேற்கிறோம்','ஒரே நிமிடத்தில், உங்கள் விழாவின் மொய்யை ஆரம்பம் முதல் முடிவு வரை எப்படி நடத்துவது என்று பாருங்கள்.'],['உங்கள் விழாவை உருவாக்குங்கள்','“நிகழ்வு / விழா உருவாக்கு” என்பதைத் தொடுங்கள். பெயர், தேதி, நேரம், இடம், மொய் பெறும் வழிகளைச் சேருங்கள்.'],['உதவியாளர்களைச் சேருங்கள்','தேவையான அளவு மொய் வசூலிப்பவர்களையும் நிகழ்வு நிர்வாகிகளையும் சேர்க்கலாம். ஒவ்வொருவரும் எதைத் திறக்கலாம் என்று தேர்வு செய்யுங்கள்.'],['கவுண்டரில் மொய் பெறுங்கள்','விருந்தினரின் மொபைல் எண்ணை டைப் செய்யுங்கள். தெரிந்தவர்களின் விவரம் தானாக வரும். தொகையை எழுதிச் சேமியுங்கள்.'],['WhatsApp-இல் ரசீது','விருந்தினருக்கு உடனே WhatsApp அல்லது SMS-இல் ரசீது போகும்.'],['விருந்தினர்களுக்கான QR பக்கம்','விருந்தினர்கள் QR-ஐ ஸ்கேன் செய்து UPI அல்லது ஆன்லைனில் மொய் செலுத்தலாம். ரொக்கம் கவுண்டரில் உறுதி செய்யப்படும்.'],['மொய் பட்டியல்','எல்லா மொய்யையும் பாருங்கள். தேடுங்கள், நெருங்கிய உறவினர்களை மேலே பின் செய்யுங்கள், திருப்பிச் செய்ததைக் குறியுங்கள்.'],['செலவுகளும் பணம் எடுப்பும்','ஒவ்வொரு செலவையும் ஒவ்வொரு பணம் எடுப்பையும் பதிவு செய்யுங்கள்; இருப்பு எப்போதும் சரியாக இருக்கும்.'],['மொய் புத்தகம்','விழா முடிந்ததும், மொய் புத்தக PDF உங்கள் WhatsApp-க்கும் மின்னஞ்சலுக்கும் வரும்.'],['வழி தெரிந்துகொள்ளுங்கள்','மெனுவைப் பயன்படுத்துங்கள்: முகப்பு, எங்கள் விழாக்கள், விருந்தினர் பட்டியல், நினைவூட்டல்கள், கிரெடிட்கள்.'],['நீங்கள் தயார்!','இப்போதே உங்கள் முதல் விழாவை உருவாக்குங்கள். இந்த வீடியோவை முகப்பில் எப்போது வேண்டுமானாலும் மீண்டும் பார்க்கலாம்.']],
hi:[['Moi Point में आपका स्वागत है','एक मिनट में देखिए कि अपने समारोह का मोई शुरू से आख़िर तक कैसे संभालें।'],['अपना समारोह बनाइए','“इवेंट / समारोह बनाएँ” दबाइए। नाम, तारीख़, समय, जगह और मोई लेने के तरीके जोड़िए।'],['अपने सहायक जोड़िए','जितने चाहें मोई कलेक्टर और इवेंट एडमिन जोड़िए। हर किसी के लिए चुनिए कि वह क्या खोल सकता है।'],['काउंटर पर मोई लीजिए','मेहमान का मोबाइल नंबर लिखिए। जाने-पहचाने मेहमानों की जानकारी अपने आप भर जाती है। रकम लिखकर सेव कीजिए।'],['WhatsApp पर रसीद','मेहमान को तुरंत WhatsApp या SMS पर रसीद मिल जाती है।'],['मेहमानों के लिए QR पेज','मेहमान QR स्कैन करके UPI या ऑनलाइन मोई दे सकते हैं। नकद काउंटर पर पक्का होता है।'],['मोई सूची','हर मोई देखिए। खोजिए, क़रीबी रिश्तेदारों को ऊपर पिन कीजिए और लौटाया हुआ मोई चिह्नित कीजिए।'],['ख़र्च और भुगतान','हर ख़र्च और हर भुगतान लिखिए, ताकि बैलेंस हमेशा सही रहे।'],['मोई बुक','समारोह ख़त्म होते ही मोई बुक की PDF आपके WhatsApp और ईमेल पर आ जाती है।'],['रास्ता जानिए','मेन्यू से जाइए: होम, हमारे समारोह, मेहमान सूची, रिमाइंडर और क्रेडिट।'],['आप तैयार हैं','अभी अपना पहला समारोह बनाइए। यह वीडियो होम से कभी भी दोबारा देखिए।']],
te:[['Moi Point కి స్వాగతం','ఒక్క నిమిషంలో, మీ వేడుక మొయ్‌ను మొదటి నుంచి చివరి వరకు ఎలా నడపాలో చూడండి.'],['మీ వేడుకను సృష్టించండి','“ఈవెంట్ / వేడుక సృష్టించు” నొక్కండి. పేరు, తేదీ, సమయం, వేదిక, మొయ్ తీసుకునే మార్గాలు చేర్చండి.'],['మీ సహాయకులను చేర్చండి','కావలసినంత మంది మొయ్ కలెక్టర్లను, ఈవెంట్ అడ్మిన్లను చేర్చండి. ఒక్కొక్కరు ఏమి తెరవగలరో ఎంచుకోండి.'],['కౌంటర్‌లో మొయ్ తీసుకోండి','అతిథి మొబైల్ నంబర్ టైప్ చేయండి. తెలిసిన అతిథుల వివరాలు వాటంతట అవే నిండుతాయి. మొత్తం రాసి సేవ్ చేయండి.'],['WhatsApp లో రసీదు','అతిథికి వెంటనే WhatsApp లేదా SMS లో రసీదు వస్తుంది.'],['అతిథుల కోసం QR పేజీ','అతిథులు QR స్కాన్ చేసి UPI లేదా ఆన్‌లైన్‌లో మొయ్ ఇవ్వవచ్చు. నగదు కౌంటర్‌లో నిర్ధారిస్తారు.'],['మొయ్ జాబితా','ప్రతి మొయ్‌ను చూడండి. వెతకండి, దగ్గరి బంధువులను పైన పిన్ చేయండి, తిరిగి ఇచ్చినవి గుర్తించండి.'],['ఖర్చులు, చెల్లింపులు','ప్రతి ఖర్చు, ప్రతి చెల్లింపు నమోదు చేయండి; బ్యాలెన్స్ ఎప్పుడూ సరిగ్గా ఉంటుంది.'],['మొయ్ బుక్','వేడుక ముగియగానే మొయ్ బుక్ PDF మీ WhatsApp కి, ఈమెయిల్‌కి వస్తుంది.'],['దారి తెలుసుకోండి','మెనూ వాడండి: హోమ్, మా వేడుకలు, అతిథుల జాబితా, రిమైండర్లు, క్రెడిట్లు.'],['మీరు సిద్ధం','ఇప్పుడే మీ మొదటి వేడుకను సృష్టించండి. ఈ వీడియోను హోమ్ నుంచి ఎప్పుడైనా మళ్ళీ చూడండి.']],
ml:[['Moi Point-ലേക്ക് സ്വാഗതം','ഒരു മിനിറ്റിൽ, നിങ്ങളുടെ ചടങ്ങിലെ മൊയ് തുടക്കം മുതൽ ഒടുക്കം വരെ എങ്ങനെ നടത്താമെന്ന് കാണൂ.'],['നിങ്ങളുടെ ചടങ്ങ് സൃഷ്ടിക്കൂ','“ഇവന്റ് / ചടങ്ങ് സൃഷ്ടിക്കുക” തൊടൂ. പേര്, തീയതി, സമയം, വേദി, മൊയ് സ്വീകരിക്കുന്ന വഴികൾ ചേർക്കൂ.'],['സഹായികളെ ചേർക്കൂ','വേണ്ടത്ര മൊയ് കളക്ടർമാരെയും ഇവന്റ് അഡ്മിൻമാരെയും ചേർക്കാം. ഓരോരുത്തർക്കും എന്ത് തുറക്കാമെന്ന് തിരഞ്ഞെടുക്കൂ.'],['കൗണ്ടറിൽ മൊയ് സ്വീകരിക്കൂ','അതിഥിയുടെ മൊബൈൽ നമ്പർ ടൈപ്പ് ചെയ്യൂ. പരിചയമുള്ളവരുടെ വിവരം സ്വയം നിറയും. തുക എഴുതി സേവ് ചെയ്യൂ.'],['WhatsApp-ൽ രസീത്','അതിഥിക്ക് ഉടൻ WhatsApp-ലോ SMS-ലോ രസീത് ലഭിക്കും.'],['അതിഥികൾക്കുള്ള QR പേജ്','അതിഥികൾക്ക് QR സ്കാൻ ചെയ്ത് UPI-യിലോ ഓൺലൈനായോ മൊയ് നൽകാം. പണം കൗണ്ടറിൽ ഉറപ്പാക്കും.'],['മൊയ് പട്ടിക','എല്ലാ മൊയും കാണൂ. തിരയൂ, അടുത്ത ബന്ധുക്കളെ മുകളിൽ പിൻ ചെയ്യൂ, തിരിച്ചു നൽകിയത് അടയാളപ്പെടുത്തൂ.'],['ചെലവുകളും പണമടവുകളും','എല്ലാ ചെലവും എല്ലാ പണമടവും രേഖപ്പെടുത്തൂ; ബാക്കി എപ്പോഴും ശരിയായിരിക്കും.'],['മൊയ് ബുക്ക്','ചടങ്ങ് കഴിയുമ്പോൾ മൊയ് ബുക്ക് PDF നിങ്ങളുടെ WhatsApp-ലും ഇമെയിലിലും വരും.'],['വഴി അറിയൂ','മെനു ഉപയോഗിക്കൂ: ഹോം, ഞങ്ങളുടെ ചടങ്ങുകൾ, അതിഥി പട്ടിക, ഓർമ്മപ്പെടുത്തലുകൾ, ക്രെഡിറ്റുകൾ.'],['നിങ്ങൾ തയ്യാർ','ഇപ്പോൾ തന്നെ ആദ്യ ചടങ്ങ് സൃഷ്ടിക്കൂ. ഈ വീഡിയോ ഹോമിൽ നിന്ന് എപ്പോൾ വേണമെങ്കിലും വീണ്ടും കാണാം.']],
kn:[['Moi Point ಗೆ ಸ್ವಾಗತ','ಒಂದೇ ನಿಮಿಷದಲ್ಲಿ, ನಿಮ್ಮ ಸಮಾರಂಭದ ಮೊಯ್ ಅನ್ನು ಆರಂಭದಿಂದ ಕೊನೆಯವರೆಗೆ ಹೇಗೆ ನಡೆಸುವುದು ನೋಡಿ.'],['ನಿಮ್ಮ ಸಮಾರಂಭ ರಚಿಸಿ','“ಈವೆಂಟ್ / ಸಮಾರಂಭ ರಚಿಸಿ” ಒತ್ತಿ. ಹೆಸರು, ದಿನಾಂಕ, ಸಮಯ, ಸ್ಥಳ ಮತ್ತು ಮೊಯ್ ಪಡೆಯುವ ವಿಧಾನಗಳನ್ನು ಸೇರಿಸಿ.'],['ಸಹಾಯಕರನ್ನು ಸೇರಿಸಿ','ಬೇಕಾದಷ್ಟು ಮೊಯ್ ಕಲೆಕ್ಟರ್‌ಗಳು ಮತ್ತು ಈವೆಂಟ್ ಅಡ್ಮಿನ್‌ಗಳನ್ನು ಸೇರಿಸಿ. ಪ್ರತಿಯೊಬ್ಬರೂ ಏನು ತೆರೆಯಬಹುದು ಎಂದು ಆರಿಸಿ.'],['ಕೌಂಟರ್‌ನಲ್ಲಿ ಮೊಯ್ ಪಡೆಯಿರಿ','ಅತಿಥಿಯ ಮೊಬೈಲ್ ಸಂಖ್ಯೆ ಟೈಪ್ ಮಾಡಿ. ಪರಿಚಿತರ ವಿವರ ತಾನಾಗಿ ತುಂಬುತ್ತದೆ. ಮೊತ್ತ ಬರೆದು ಸೇವ್ ಮಾಡಿ.'],['WhatsApp ನಲ್ಲಿ ರಸೀದಿ','ಅತಿಥಿಗೆ ತಕ್ಷಣ WhatsApp ಅಥವಾ SMS ನಲ್ಲಿ ರಸೀದಿ ಬರುತ್ತದೆ.'],['ಅತಿಥಿಗಳಿಗಾಗಿ QR ಪುಟ','ಅತಿಥಿಗಳು QR ಸ್ಕ್ಯಾನ್ ಮಾಡಿ UPI ಅಥವಾ ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಮೊಯ್ ನೀಡಬಹುದು. ನಗದು ಕೌಂಟರ್‌ನಲ್ಲಿ ಖಚಿತವಾಗುತ್ತದೆ.'],['ಮೊಯ್ ಪಟ್ಟಿ','ಎಲ್ಲಾ ಮೊಯ್ ನೋಡಿ. ಹುಡುಕಿ, ಹತ್ತಿರದ ಸಂಬಂಧಿಕರನ್ನು ಮೇಲೆ ಪಿನ್ ಮಾಡಿ, ಹಿಂದಿರುಗಿಸಿದ್ದನ್ನು ಗುರುತಿಸಿ.'],['ಖರ್ಚು ಮತ್ತು ಪಾವತಿಗಳು','ಪ್ರತಿ ಖರ್ಚು ಮತ್ತು ಪ್ರತಿ ಪಾವತಿಯನ್ನು ದಾಖಲಿಸಿ; ಬಾಕಿ ಯಾವಾಗಲೂ ಸರಿಯಾಗಿರುತ್ತದೆ.'],['ಮೊಯ್ ಪುಸ್ತಕ','ಸಮಾರಂಭ ಮುಗಿದಾಗ ಮೊಯ್ ಪುಸ್ತಕದ PDF ನಿಮ್ಮ WhatsApp ಮತ್ತು ಇಮೇಲ್‌ಗೆ ಬರುತ್ತದೆ.'],['ದಾರಿ ತಿಳಿಯಿರಿ','ಮೆನು ಬಳಸಿ: ಮುಖಪುಟ, ನಮ್ಮ ಸಮಾರಂಭಗಳು, ಅತಿಥಿ ಪಟ್ಟಿ, ಜ್ಞಾಪನೆಗಳು ಮತ್ತು ಕ್ರೆಡಿಟ್‌ಗಳು.'],['ನೀವು ಸಿದ್ಧ','ಈಗಲೇ ನಿಮ್ಮ ಮೊದಲ ಸಮಾರಂಭ ರಚಿಸಿ. ಈ ವೀಡಿಯೊವನ್ನು ಮುಖಪುಟದಿಂದ ಯಾವಾಗ ಬೇಕಾದರೂ ಮತ್ತೆ ನೋಡಿ.']],
mr:[['Moi Point मध्ये स्वागत','एका मिनिटात पाहा, तुमच्या समारंभाचा मोई सुरुवातीपासून शेवटपर्यंत कसा सांभाळायचा.'],['तुमचा समारंभ तयार करा','“इव्हेंट / समारंभ तयार करा” दाबा. नाव, तारीख, वेळ, ठिकाण आणि मोई घेण्याचे मार्ग जोडा.'],['मदतनीस जोडा','हवे तितके मोई कलेक्टर आणि इव्हेंट ॲडमिन जोडा. प्रत्येकजण काय उघडू शकतो ते निवडा.'],['काउंटरवर मोई घ्या','पाहुण्याचा मोबाइल नंबर टाइप करा. ओळखीच्या पाहुण्यांची माहिती आपोआप भरते. रक्कम लिहून सेव्ह करा.'],['WhatsApp वर पावती','पाहुण्याला लगेच WhatsApp किंवा SMS वर पावती मिळते.'],['पाहुण्यांसाठी QR पेज','पाहुणे QR स्कॅन करून UPI किंवा ऑनलाइन मोई देऊ शकतात. रोख काउंटरवर पक्की होते.'],['मोई यादी','प्रत्येक मोई पाहा. शोधा, जवळच्या नातेवाइकांना वर पिन करा आणि परत केलेले चिन्हांकित करा.'],['खर्च आणि पेमेंट','प्रत्येक खर्च आणि प्रत्येक पेमेंट नोंदवा, म्हणजे शिल्लक नेहमी बरोबर राहील.'],['मोई बुक','समारंभ संपताच मोई बुकची PDF तुमच्या WhatsApp आणि ईमेलवर येते.'],['मार्ग जाणून घ्या','मेनू वापरा: होम, आमचे समारंभ, पाहुण्यांची यादी, रिमाइंडर आणि क्रेडिट.'],['तुम्ही तयार आहात','आत्ताच तुमचा पहिला समारंभ तयार करा. हा व्हिडिओ होमवरून कधीही पुन्हा पाहा.']],
gu:[['Moi Point માં સ્વાગત છે','એક મિનિટમાં જુઓ કે તમારા પ્રસંગનો મોઈ શરૂઆતથી અંત સુધી કેવી રીતે સંભાળવો.'],['તમારો પ્રસંગ બનાવો','“ઇવેન્ટ / પ્રસંગ બનાવો” દબાવો. નામ, તારીખ, સમય, સ્થળ અને મોઈ લેવાની રીતો ઉમેરો.'],['મદદનીશ ઉમેરો','જેટલા જોઈએ તેટલા મોઈ કલેક્ટર અને ઇવેન્ટ એડમિન ઉમેરો. દરેક શું ખોલી શકે તે પસંદ કરો.'],['કાઉન્ટર પર મોઈ લો','મહેમાનનો મોબાઇલ નંબર લખો. ઓળખીતા મહેમાનની વિગતો આપોઆપ ભરાય છે. રકમ લખીને સેવ કરો.'],['WhatsApp પર રસીદ','મહેમાનને તરત WhatsApp અથવા SMS પર રસીદ મળે છે.'],['મહેમાનો માટે QR પેજ','મહેમાનો QR સ્કેન કરીને UPI અથવા ઓનલાઇન મોઈ આપી શકે છે. રોકડ કાઉન્ટર પર પાકી થાય છે.'],['મોઈ યાદી','દરેક મોઈ જુઓ. શોધો, નજીકના સગાંને ઉપર પિન કરો અને પાછું આપેલું ચિહ્નિત કરો.'],['ખર્ચ અને ચુકવણી','દરેક ખર્ચ અને દરેક ચુકવણી નોંધો, જેથી બેલેન્સ હંમેશા સાચું રહે.'],['મોઈ બુક','પ્રસંગ પૂરો થતાં જ મોઈ બુકની PDF તમારા WhatsApp અને ઇમેઇલ પર આવે છે.'],['રસ્તો જાણો','મેનુ વાપરો: હોમ, અમારા પ્રસંગો, મહેમાન યાદી, રિમાઇન્ડર અને ક્રેડિટ.'],['તમે તૈયાર છો','હમણાં જ તમારો પહેલો પ્રસંગ બનાવો. આ વીડિયો હોમ પરથી ક્યારેય પણ ફરી જુઓ.']],
bn:[['Moi Point-এ স্বাগত','এক মিনিটে দেখুন, আপনার অনুষ্ঠানের মোই শুরু থেকে শেষ পর্যন্ত কীভাবে সামলাবেন।'],['আপনার অনুষ্ঠান তৈরি করুন','“ইভেন্ট / অনুষ্ঠান তৈরি করুন” চাপুন। নাম, তারিখ, সময়, জায়গা আর মোই নেওয়ার উপায় যোগ করুন।'],['সহকারী যোগ করুন','যত খুশি মোই কালেক্টর আর ইভেন্ট অ্যাডমিন যোগ করুন। কে কী খুলতে পারবে তা বেছে নিন।'],['কাউন্টারে মোই নিন','অতিথির মোবাইল নম্বর লিখুন। চেনা অতিথির তথ্য নিজে থেকেই ভরে যায়। টাকার অঙ্ক লিখে সেভ করুন।'],['WhatsApp-এ রসিদ','অতিথি সঙ্গে সঙ্গে WhatsApp বা SMS-এ রসিদ পান।'],['অতিথিদের জন্য QR পেজ','অতিথিরা QR স্ক্যান করে UPI বা অনলাইনে মোই দিতে পারেন। নগদ কাউন্টারে নিশ্চিত হয়।'],['মোই তালিকা','সব মোই দেখুন। খুঁজুন, কাছের আত্মীয়দের উপরে পিন করুন, ফেরত দেওয়াগুলো চিহ্নিত করুন।'],['খরচ ও পেমেন্ট','প্রতিটি খরচ আর প্রতিটি পেমেন্ট লিখে রাখুন, যাতে ব্যালান্স সবসময় ঠিক থাকে।'],['মোই বুক','অনুষ্ঠান শেষ হলেই মোই বুকের PDF আপনার WhatsApp আর ইমেলে আসে।'],['পথ চিনে নিন','মেনু ব্যবহার করুন: হোম, আমাদের অনুষ্ঠান, অতিথি তালিকা, রিমাইন্ডার আর ক্রেডিট।'],['আপনি তৈরি','এখনই আপনার প্রথম অনুষ্ঠান তৈরি করুন। এই ভিডিও হোম থেকে যেকোনো সময় আবার দেখুন।']],
pa:[['Moi Point ਵਿੱਚ ਜੀ ਆਇਆਂ ਨੂੰ','ਇੱਕ ਮਿੰਟ ਵਿੱਚ ਵੇਖੋ ਕਿ ਆਪਣੇ ਸਮਾਗਮ ਦਾ ਮੋਈ ਸ਼ੁਰੂ ਤੋਂ ਅਖ਼ੀਰ ਤੱਕ ਕਿਵੇਂ ਸੰਭਾਲਣਾ ਹੈ।'],['ਆਪਣਾ ਸਮਾਗਮ ਬਣਾਓ','“ਇਵੈਂਟ / ਸਮਾਗਮ ਬਣਾਓ” ਦਬਾਓ। ਨਾਂ, ਤਾਰੀਖ਼, ਸਮਾਂ, ਥਾਂ ਅਤੇ ਮੋਈ ਲੈਣ ਦੇ ਤਰੀਕੇ ਜੋੜੋ।'],['ਸਹਾਇਕ ਜੋੜੋ','ਜਿੰਨੇ ਚਾਹੋ ਮੋਈ ਕੁਲੈਕਟਰ ਅਤੇ ਇਵੈਂਟ ਐਡਮਿਨ ਜੋੜੋ। ਹਰ ਕੋਈ ਕੀ ਖੋਲ੍ਹ ਸਕਦਾ ਹੈ, ਇਹ ਚੁਣੋ।'],['ਕਾਊਂਟਰ ’ਤੇ ਮੋਈ ਲਓ','ਮਹਿਮਾਨ ਦਾ ਮੋਬਾਈਲ ਨੰਬਰ ਲਿਖੋ। ਜਾਣੂ ਮਹਿਮਾਨਾਂ ਦੀ ਜਾਣਕਾਰੀ ਆਪੇ ਭਰ ਜਾਂਦੀ ਹੈ। ਰਕਮ ਲਿਖ ਕੇ ਸੇਵ ਕਰੋ।'],['WhatsApp ’ਤੇ ਰਸੀਦ','ਮਹਿਮਾਨ ਨੂੰ ਝੱਟ WhatsApp ਜਾਂ SMS ’ਤੇ ਰਸੀਦ ਮਿਲ ਜਾਂਦੀ ਹੈ।'],['ਮਹਿਮਾਨਾਂ ਲਈ QR ਪੇਜ','ਮਹਿਮਾਨ QR ਸਕੈਨ ਕਰਕੇ UPI ਜਾਂ ਔਨਲਾਈਨ ਮੋਈ ਦੇ ਸਕਦੇ ਹਨ। ਨਕਦ ਕਾਊਂਟਰ ’ਤੇ ਪੱਕਾ ਹੁੰਦਾ ਹੈ।'],['ਮੋਈ ਸੂਚੀ','ਹਰ ਮੋਈ ਵੇਖੋ। ਲੱਭੋ, ਨੇੜਲੇ ਰਿਸ਼ਤੇਦਾਰਾਂ ਨੂੰ ਉੱਪਰ ਪਿੰਨ ਕਰੋ ਅਤੇ ਵਾਪਸ ਕੀਤੇ ’ਤੇ ਨਿਸ਼ਾਨ ਲਾਓ।'],['ਖ਼ਰਚੇ ਅਤੇ ਭੁਗਤਾਨ','ਹਰ ਖ਼ਰਚਾ ਅਤੇ ਹਰ ਭੁਗਤਾਨ ਦਰਜ ਕਰੋ, ਤਾਂ ਜੋ ਬਕਾਇਆ ਹਮੇਸ਼ਾ ਠੀਕ ਰਹੇ।'],['ਮੋਈ ਬੁੱਕ','ਸਮਾਗਮ ਮੁੱਕਦੇ ਹੀ ਮੋਈ ਬੁੱਕ ਦੀ PDF ਤੁਹਾਡੇ WhatsApp ਅਤੇ ਈਮੇਲ ’ਤੇ ਆ ਜਾਂਦੀ ਹੈ।'],['ਰਾਹ ਜਾਣੋ','ਮੀਨੂ ਵਰਤੋ: ਹੋਮ, ਸਾਡੇ ਸਮਾਗਮ, ਮਹਿਮਾਨ ਸੂਚੀ, ਰਿਮਾਈਂਡਰ ਅਤੇ ਕ੍ਰੈਡਿਟ।'],['ਤੁਸੀਂ ਤਿਆਰ ਹੋ','ਹੁਣੇ ਆਪਣਾ ਪਹਿਲਾ ਸਮਾਗਮ ਬਣਾਓ। ਇਹ ਵੀਡੀਓ ਹੋਮ ਤੋਂ ਕਦੇ ਵੀ ਦੁਬਾਰਾ ਵੇਖੋ।']],
or:[['Moi Point କୁ ସ୍ୱାଗତ','ଏକ ମିନିଟରେ ଦେଖନ୍ତୁ, ଆପଣଙ୍କ ଉତ୍ସବର ମୋଇ ଆରମ୍ଭରୁ ଶେଷ ପର୍ଯ୍ୟନ୍ତ କିପରି ସମ୍ଭାଳିବେ।'],['ଆପଣଙ୍କ ଉତ୍ସବ ତିଆରି କରନ୍ତୁ','“ଇଭେଣ୍ଟ / ଉତ୍ସବ ତିଆରି କରନ୍ତୁ” ଦବାନ୍ତୁ। ନାମ, ତାରିଖ, ସମୟ, ସ୍ଥାନ ଏବଂ ମୋଇ ନେବାର ଉପାୟ ଯୋଡନ୍ତୁ।'],['ସହାୟକ ଯୋଡନ୍ତୁ','ଯେତେ ଦରକାର ମୋଇ କଲେକ୍ଟର ଓ ଇଭେଣ୍ଟ ଆଡମିନ ଯୋଡନ୍ତୁ। କିଏ କଣ ଖୋଲିପାରିବ ବାଛନ୍ତୁ।'],['କାଉଣ୍ଟରରେ ମୋଇ ନିଅନ୍ତୁ','ଅତିଥିଙ୍କ ମୋବାଇଲ ନମ୍ବର ଲେଖନ୍ତୁ। ଚିହ୍ନା ଅତିଥିଙ୍କ ତଥ୍ୟ ନିଜେ ଭରିଯାଏ। ରାଶି ଲେଖି ସେଭ କରନ୍ତୁ।'],['WhatsApp ରେ ରସିଦ','ଅତିଥି ତୁରନ୍ତ WhatsApp କିମ୍ବା SMS ରେ ରସିଦ ପାଆନ୍ତି।'],['ଅତିଥିଙ୍କ ପାଇଁ QR ପେଜ','ଅତିଥି QR ସ୍କାନ କରି UPI କିମ୍ବା ଅନଲାଇନରେ ମୋଇ ଦେଇପାରିବେ। ନଗଦ କାଉଣ୍ଟରରେ ନିଶ୍ଚିତ ହୁଏ।'],['ମୋଇ ତାଲିକା','ସବୁ ମୋଇ ଦେଖନ୍ତୁ। ଖୋଜନ୍ତୁ, ନିକଟ ସମ୍ପର୍କୀୟଙ୍କୁ ଉପରେ ପିନ କରନ୍ତୁ, ଫେରାଇଥିବା ଚିହ୍ନଟ କରନ୍ତୁ।'],['ଖର୍ଚ୍ଚ ଓ ପେମେଣ୍ଟ','ପ୍ରତ୍ୟେକ ଖର୍ଚ୍ଚ ଓ ପେମେଣ୍ଟ ଲେଖନ୍ତୁ, ଯେପରି ବାଲାନ୍ସ ସବୁବେଳେ ଠିକ ରହେ।'],['ମୋଇ ବୁକ','ଉତ୍ସବ ଶେଷ ହେବା ମାତ୍ରେ ମୋଇ ବୁକର PDF ଆପଣଙ୍କ WhatsApp ଓ ଇମେଲକୁ ଆସେ।'],['ରାସ୍ତା ଜାଣନ୍ତୁ','ମେନୁ ବ୍ୟବହାର କରନ୍ତୁ: ହୋମ, ଆମ ଉତ୍ସବ, ଅତିଥି ତାଲିକା, ରିମାଇଣ୍ଡର ଓ କ୍ରେଡିଟ।'],['ଆପଣ ପ୍ରସ୍ତୁତ','ଏବେ ଆପଣଙ୍କ ପ୍ରଥମ ଉତ୍ସବ ତିଆରି କରନ୍ତୁ। ଏହି ଭିଡିଓ ହୋମରୁ ଯେକୌଣସି ସମୟରେ ପୁଣି ଦେଖନ୍ତୁ।']]};
const VSEC=5.6;
const vid={on:false,i:0,t0:0,el:0,play:false,raf:0,lg:'en',music:true,ctx:null,mg:null,tm:0};
const vLg=()=>VSUB[vid.lg]?vid.lg:'en';
function vidOpen(auto){vid.on=true;vid.i=0;vid.el=0;vid.lg=VSUB[UIL]?UIL:'en';vid.auto=!!auto;const o=document.createElement('div');o.id='vid';o.className='vid'+(vidCC?'':' cc-off');o.setAttribute('role','dialog');o.setAttribute('aria-label','How to use Moi Point');o.dataset.noi18n='';
  o.innerHTML=`<div class="vid-box"><div class="vid-stage" id="vidStage"></div><div class="vid-sub" id="vidSub" aria-live="polite"></div>
   <div class="vid-ctl"><button class="vc" data-act="vidPlay" id="vidPlayB" aria-label="Pause">${VPAUSE}</button><div class="vid-bar" id="vidBar" data-act="vidSeek"><i id="vidFill"></i>${VSC.map((_,i)=>`<b style="left:${i/VSC.length*100}%"></b>`).join('')}</div><span class="vid-tm" id="vidTm">0:00 / ${vfmt(VSC.length*VSEC)}</span>
   <button class="vc" data-act="vidMusic" id="vidMusB" aria-label="Music off">${ic(vid.music?'speaker':'mute',18)}</button><button class="vc vcc" data-act="vidCC" aria-pressed="${vidCC}" aria-label="Subtitles">CC</button><label class="vid-cc"><select id="vidLg" aria-label="Subtitle language">${UILANGS.map(([k,n])=>`<option value="${k}" ${k===vid.lg?'selected':''}>${n}</option>`).join('')}</select></label><button class="vc" data-act="vidFull" aria-label="Full screen">${VFULL}</button></div>
   <div class="vid-top"><span>${ic('video',16)} How to use Moi Point · 1 min</span><div><button class="vid-skip" data-act="vidClose" data-k="skip">Skip</button><button class="vc" data-act="vidClose" aria-label="Close">${ic('x',20)}</button></div></div></div>`;
  document.body.appendChild(o);document.body.classList.add('vid-open');vidFit();vidScene(0);vidPlay(true);
  const sel=document.getElementById('vidLg');sel.onchange=()=>{vid.lg=sel.value;vidSubT()}}
