/* ---------- words: “Event / Function” and “Void / Delete” everywhere ---------- */
const WF_SKIP='.bi,.ticket,.bk,.pr-th,.paper,code,.code,.tx,script,style,textarea,.rx,.rx-live,.mail,.vid,[data-nowf],.mx td,.evc-n,.fn-t b,.evsw-n,.hc-head h1';
const WF_EN=[[/(?<![\/\-\w])Events(?![\w\-]|\s*\/)/g,'Events / Functions'],[/(?<![\/\-\w])Event(?![\w\-]|\s*\/)/g,'Event / Function'],[/(?<![\/\-\w])events(?![\w\-]|\s*\/)/g,'events / functions'],[/(?<![\/\-\w])event(?![\w\-]|\s*\/)/g,'event / function'],[/(?<![\/\-\w])Void(?![\w\-]|\s*\/)/g,'Void / Delete'],[/(?<![\/\-\w])void(?![\w\-]|\s*\/)/g,'void / delete'],[/(?<![\/\-\w])VOID(?![\w\-]|\s*\/)/g,'VOID / DELETE']];
const WF_TA=[[/(^|[\s(“"])நிகழ்வுகள்(?=$|[\s·,.:!?)”"])(?!\s*\/)/g,'$1நிகழ்வுகள் / விழாக்கள்'],[/(^|[\s(“"])நிகழ்வு(?=$|[\s·,.:!?)”"])(?!\s*\/)/g,'$1நிகழ்வு / விழா'],[/^(\s*)ரத்து(\s*)$/,'$1ரத்து / நீக்கு$2']];
function wordFix(root){if(!root)return;const R=UIL==='ta'?WF_TA:UIL==='en'?WF_EN:null;if(!R)return;const nodes=[];
  if(root.nodeType===3)nodes.push(root);else if(root.nodeType===1){if(root.closest&&root.closest(WF_SKIP))return;const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while((n=w.nextNode()))nodes.push(n)}
  nodes.forEach(nd=>{const v=nd.nodeValue;if(!v||v.length<4)return;if(UIL==='en'&&!/vent|oid|OID/.test(v))return;const p=nd.parentElement;if(!p||p.closest(WF_SKIP)||p.isContentEditable)return;let t=v;R.forEach(([re,s])=>{t=t.replace(re,s)});if(t!==v)nd.nodeValue=t})}
const wfObs=new MutationObserver(ms=>{ms.forEach(m=>m.addedNodes.forEach(wordFix))});wfObs.observe(document.body,{childList:true,subtree:true});

